"""Gate required PostgreSQL coverage and check the two real CPU integrators in CI."""

import math
import os
import sys
import xml.etree.ElementTree as xml
from pathlib import Path
from tempfile import TemporaryDirectory


def postgres_report(path):
    # The report was just generated by pytest on this CI runner.
    cases = xml.parse(path).findall(".//testcase")
    modules = {case.attrib["classname"].split(".")[-1] for case in cases}
    required = {
        "test_compute_postgres",
        "test_identity_postgres",
        "test_local_assistant_postgres",
        "test_plot_postgres",
        "test_profile_postgres",
        "test_rag_postgres",
        "test_v10_rag_boundaries",
    }
    if missing := required - modules:
        raise SystemExit(f"Required PostgreSQL coverage missing: {', '.join(sorted(missing))}")
    incomplete = [
        case.attrib["name"]
        for case in cases
        if any(case.find(item) is not None for item in ("skipped", "error", "failure"))
    ]
    if incomplete:
        raise SystemExit(f"Required PostgreSQL checks did not pass: {', '.join(incomplete)}")
    print(f"PostgreSQL coverage: {len(cases)} passing cases")


def compute():
    from astroagent.compute_io import read, write
    from astroagent.compute_runner import run

    # Isolated equal-mass circular binary. AU, solar mass, year and AU/year.
    # With a total of 1 solar mass and separation 1 AU, its period is 1 year.
    for engine, tolerance in (("rebound", 1e-8), ("petar", 1e-5)):
        with TemporaryDirectory() as directory:
            root = Path(directory)
            previous = Path.cwd()
            try:
                os.chdir(root)
                particles = [
                    {
                        "id": name,
                        "mass": 0.5,
                        "position": [sign * 0.5, 0.0, 0.0],
                        "velocity": [0.0, sign * math.pi, 0.0],
                    }
                    for name, sign in (("a", -1), ("b", 1))
                ]
                write(
                    root / "input",
                    {"engine": engine, "duration": 1.0, "samples": 5, "particles": particles},
                )
                run(root)
                result = read(root / "result")
            finally:
                os.chdir(previous)
        if result["engine"] != engine or len(result["samples"]) != 5:
            raise SystemExit(f"{engine}: wrong engine or sample count")
        for index, sample in enumerate(result["samples"]):
            first = sample["particles"][0]["position"]
            second = sample["particles"][1]["position"]
            if (
                not math.isclose(sample["time"], index / 4, rel_tol=0, abs_tol=1e-12)
                or abs(math.dist(first, second) - 1) > tolerance
                or abs(sample["energy_relative"]) > tolerance
            ):
                raise SystemExit(f"{engine}: circular orbit separation or energy outside tolerance")
        final = result["samples"][-1]["particles"][0]["position"]
        if math.dist(final, particles[0]["position"]) > 10 * tolerance:
            raise SystemExit(f"{engine}: the particle did not return after one period")
        print(f"{engine}: real circular orbit run passed, tolerance {tolerance:g}")


if __name__ == "__main__":
    if sys.argv[1:] == ["compute"]:
        compute()
    elif len(sys.argv) == 3 and sys.argv[1] == "postgres":
        postgres_report(sys.argv[2])
    else:
        raise SystemExit("Use compute or postgres <junit-report>.")
